/**
 * Baked city grids, classified from OpenStreetMap raster tiles.
 *
 * Each row is run-length encoded as count+character pairs, where `.` is
 * land, `R` road, `W` water, `B` building and `G` green. Carried across from
 * the prototype unchanged — this is data, not a derivation, and it ships in
 * the repo so the animations need no network at runtime.
 */

export type CityCell = 0 | 1 | 2 | 3 | 4;

/** Cell codes, in the order the encoding uses. */
export const LAND = 0;
export const ROAD = 1;
export const WATER = 2;
export const BUILDING = 3;
export const GREEN = 4;

export interface EncodedCityGrid {
  /** Grid is square, this many cells per side. */
  g: number;
  /** Source tile zoom level. */
  z: number;
  /** Latitude and longitude of the grid centre. */
  center: [number, number];
  rows: string[];
}

export interface CityGridData {
  g: number;
  cells: Uint8Array;
  center: [number, number];
  z: number;
}

export type CityGridId = 'pgh14' | 'pdx14' | 'pgh16' | 'pdx16';

