const cache = new Map<CityGridId, CityGridData>();

/** Expand a run-length encoded grid into one byte per cell. */
export function cityGridData(id: CityGridId): CityGridData {
  const hit = cache.get(id);
  if (hit) return hit;
  const grid = GRIDS[id];
  const G = grid.g;
  const cells = new Uint8Array(G * G);
  for (let y = 0; y < G; y++) {
    let x = 0;
    const re = /(\d+)([RWBG.])/g;
    let m: RegExpExecArray | null;
    while ((m = re.exec(grid.rows[y]))) {
      const n = +m[1];
      const c = CODE[m[2]];
      for (let i = 0; i < n; i++) cells[y * G + x++] = c;
    }
  }
  const value: CityGridData = { g: G, cells, center: grid.center, z: grid.z };
  cache.set(id, value);
  return value;
}
